package workshop.vfx.paper.m8;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static workshop.vfx.paper.m8.K1Fixture.*;
import java.util.*;
import workshop.vfx.delivery.*;
import workshop.vfx.paper.core.*;
import workshop.vfx.scene.*;

class K1IdentityAndPermissionsTest {
    @Test void ownersWithUseButNoViewSeeOnlyTheirOwnAura(){var f=new K1Fixture();f.balanced();f.auras.start(B,QualityTier.SIMPLE,f.tick);f.run();assertEquals(34,f.sendsTo(A));assertEquals(20,f.sendsTo(B));f.account();}
    @Test void viewerPermissionGrantRevokeAndOwnerUseAreRechecked(){var f=new K1Fixture();f.balanced();f.run();assertEquals(0,f.sendsTo(B));f.canView.add(B);f.step();assertEquals(34,f.sendsTo(B));f.canView.clear();f.noUse.add(A);f.step();assertEquals(0,f.sendsTo(A));assertEquals(0,f.sendsTo(B));}
    @Test void permissionRevokedBetweenPlanningAndEmissionIsFailClosed(){var f=new K1Fixture();f.balanced();f.canView.add(B);f.afterPlan=()->{f.noUse.add(A);f.canView.clear();};f.run();assertEquals(0,f.sends.size());assertEquals(68,f.driver.lastReport().placementsInSkippedRecipients());f.account();}
    @Test void viewersMustBeInCurrentWorldAndRange(){var f=new K1Fixture();f.balanced();f.canView.add(B);f.position.get(B)[0]=33;f.run();assertEquals(0,f.sendsTo(B));f.position.get(B)[0]=0;f.worlds.put(B,W2);f.step();assertEquals(0,f.sendsTo(B));f.worlds.put(A,W2);f.step();assertEquals(34,f.sendsTo(B));assertTrue(f.sends.stream().allMatch(s->s.world()==f.ids.worldId(W2)));}
    @Test void ownerFirstSelectionUnderOneViewerCap(){var f=new K1Fixture(Map.of("maxViewersPerEffect",1),Map.of());f.ids.viewerId(B);f.balanced();f.canView.add(B);f.run();assertEquals(34,f.sendsTo(A));assertEquals(0,f.sendsTo(B));}
    @Test void forgedOwnerTerminatesBeforeAnyUnauthorizedEmission(){var f=new K1Fixture();f.balanced();f.tamper=s->replace(s,null,B,null,null,null,null,null,null,null,null,null);f.run();assertEquals(0,f.sendsTo(B));assertEquals(0,f.registry.activeCount());assertEquals(1,f.registry.rejections(AnchorRejection.OWNER_MISMATCH));}
    @Test void forgedViewerAndReleasedBindingTerminate(){for(boolean release:List.of(false,true)){var f=new K1Fixture();f.balanced();long id=f.ids.viewerId(B);if(release)f.ids.release(A);else f.tamper=s->replace(s,null,null,id,null,null,null,null,null,null,null,null);f.run();assertFalse(f.registry.active());assertEquals(0,f.sends.size());assertEquals(1,f.registry.rejections(AnchorRejection.VIEWER_ID_MISMATCH));}}
    @Test void staleAndFutureSnapshotsSkipThenRecoverWithoutRestartingClock(){for(long delta:new long[]{-1,1,-1000}){var f=new K1Fixture();f.balanced();f.tamper=s->replace(s,s.tick()+delta,null,null,null,null,null,null,null,null,null,null);f.tick=105;f.run();assertEquals(0,f.plans);assertTrue(f.registry.active());f.tamper=java.util.function.UnaryOperator.identity();f.step();assertEquals(6,f.requests.getFirst().frameOrdinal());assertEquals(34,f.sends.size());}}
    @Test void nonfinitePositionAndYawAxesNeverReachPlanner(){for(int field=0;field<5;field++)for(double bad:new double[]{Double.NaN,Double.POSITIVE_INFINITY,Double.NEGATIVE_INFINITY}){var f=new K1Fixture();f.balanced();int k=field;f.tamper=s->replace(s,null,null,null,null,null,k==0?bad:null,k==1?bad:null,k==2?bad:null,k==3?(float)bad:null,k==4?(float)bad:null,null);f.run();assertEquals(0,f.plans);assertEquals(1,f.registry.rejections(AnchorRejection.NON_FINITE));}}
    @Test void unknownMismatchedWorldHeightAndChunkFailClosed(){for(int n=0;n<5;n++){var f=new K1Fixture();f.balanced();int k=n;f.tamper=s->replace(s,null,null,null,k==0?W2:null,k==1?Integer.MAX_VALUE:null,null,k==2?Double.valueOf(320):k==3?Double.valueOf(-65):null,null,null,null,k==4?false:null);f.run();assertEquals(0,f.plans);assertEquals(0,f.sends.size());assertTrue(f.registry.active());}}
    @Test void invalidStreakTerminatesAtConfiguredLimitAndReadyResetsIt(){var f=new K1Fixture(Map.of(),Map.of("invalidAnchorTicksToTerminate",3));f.balanced();f.tamper=s->replace(s,s.tick()-1,null,null,null,null,null,null,null,null,null,null);f.run();f.step();assertTrue(f.registry.active());f.tamper=java.util.function.UnaryOperator.identity();f.step();assertEquals(34,f.sends.size());f.tamper=s->null;f.step();assertFalse(f.registry.active());var g=new K1Fixture();g.balanced();g.tamper=s->replace(s,s.tick()-1,null,null,null,null,null,null,null,null,null,null);for(int i=0;i<19;i++){g.run();assertTrue(g.registry.active());g.tick++;}g.run();assertFalse(g.registry.active());}
    @Test void realAuraDraftUsesBoundIdentityAndRejectsTamperedDirectContributions(){var f=new K1Fixture();f.balanced();var e=f.current();var s=f.snapshot(A,f.tick);assertTrue(e.contribute(f.tick,replace(s,null,B,f.ids.viewerId(B),null,null,null,null,null,null,null,null)).isEmpty());var d=e.contribute(f.tick,s).orElseThrow();assertEquals(A,d.owner());assertEquals(f.ids.viewerId(A),d.ownerViewerId());assertTrue(d.requestId()>=DynamicEffectRegistry.FIRST_ID);assertEquals(0,f.registry.identityViolations());}
}
